"""Task pages grounded in the November 11 hourly GSC export."""
from pathlib import Path
from site_analytics import write_html

ROOT = Path(__file__).resolve().parents[1]
BASE = '/warhammer-survivors/'
XBOX = 'https://www.xbox.com/en-us/games/store/warhammer-survivors/9mzzwgtf7v65'
ANYWHERE = 'https://www.xbox.com/en-US/games/xbox-play-anywhere'
STEAM = 'https://store.steampowered.com/app/3669620/Warhammer_Survivors/'
AMA = 'https://www.reddit.com/r/Games/comments/1xbobvf/were_auroch_digital_ask_us_anything_about_our/'
ITEMS = 'https://www.destructoid.com/all-items-in-warhammer-survivors-and-how-to-unlock-them/'
FOLLOWERS = 'https://www.destructoid.com/how-to-gain-more-followers-in-warhammer-survivors/'
CHARACTERS = 'https://www.destructoid.com/all-characters-in-warhammer-survivors-and-how-to-unlock-them/'

def build(template):
    from warhammer_survivors_pages import render, image, external
    visual = image('squad', 'A champion with armed allies beside a tank in Warhammer Survivors', 'Official gameplay image. © Games Workshop Limited. Historical capture build unspecified.')
    combat = image('combat', 'A Warhammer Survivors champion using weapons against enemies in a courtyard', 'Official development gameplay image. © Games Workshop Limited.')
    objectives = '<figure><a href="/assets/warhammer-survivors/objectives.webp"><img src="/assets/warhammer-survivors/objectives.webp" width="839" height="472" alt="Warhammer Survivors Objectives menu showing Have 2 Followers and the Bugman’s Tankard reward" loading="lazy"></a><figcaption>Objectives menu screenshot by Destructoid. Game art © Games Workshop Limited.</figcaption></figure>'
    visual = objectives
    pages = [
        ('cross-save', 'Warhammer Survivors Cross-Save: What Progress Transfers', 'Check Warhammer Survivors save transfer by storefront, including Xbox Play Anywhere, Steam Cloud, mobile copies and the demo progress boundary.', 'Warhammer Survivors cross-save and progress transfer',
         '<p><strong>Xbox Play Anywhere supports progress between the Xbox and Microsoft PC versions.</strong> For Steam, mobile, PlayStation and Nintendo combinations, a general cross-save connection has not been confirmed. Check the exact two versions before buying another copy.</p>', [
            ('versions', 'Match the two storefronts first', f'<p>The {external(XBOX, "official Xbox product listing")} carries both Xbox Play Anywhere and Xbox cloud saves. Microsoft describes Play Anywhere as carrying saves and achievements between Xbox console, PC and supported handhelds. Together these establish the Microsoft-version route. {external(ANYWHERE, "Microsoft Play Anywhere rules")}</p><div class="table-wrap" tabindex="0" role="region" aria-label="Save transfer by version"><table><thead><tr><th>Your copies</th><th>Documented support</th><th>Next step</th></tr></thead><tbody><tr><td>Xbox Series X|S and Microsoft PC</td><td>Xbox Play Anywhere and cloud saves</td><td>Use the same Microsoft/Xbox account and allow synchronization to finish.</td></tr><tr><td>Steam on two PCs or Steam Deck</td><td>Steam lists Steam Cloud</td><td>Check Steam Cloud status for the game before switching devices.</td></tr><tr><td>Steam and Microsoft PC</td><td>No automatic transfer established</td><td>Check which store owns each installation, even on the same PC.</td></tr><tr><td>Steam and iOS/Android, or console and mobile</td><td>General cross-store transfer unconfirmed</td><td>Confirm current developer support before buying for an existing save.</td></tr><tr><td>Demo and full game</td><td>Demo progress does not carry over</td><td>Start progression in the full version.</td></tr></tbody></table></div>'),
            ('sync', 'Switch devices through the supported route', '<ol><li>Confirm that both installations are the Microsoft version, or that both belong to the same Steam account.</li><li>Finish the session and exit the game on the first device. Keep it connected while its platform uploads the save.</li><li>Open the second device with that same account and allow the platform to synchronize before starting a new run.</li><li>If the expected progress is missing, check the account and storefront before creating more progress on the second device. Compare the platform cloud status and contact support with both device/store names.</li></ol><p>This is a platform-based checking sequence. We have not performed a two-device save-transfer test for this game.</p>'+combat),
            ('limits', 'What the developer has said about broader transfers', f'<p>In the October 27 AMA, the developer said it had nothing to announce about cross-save at that point. That answer is relevant to broader platform requests. The current Microsoft product listing provides a more specific, documented Xbox Play Anywhere route. {external(AMA, "Auroch Digital developer AMA")}</p><p>The Steam product lists Steam Cloud. That describes the Steam copy’s cloud capability. A purchase on another store still needs its own supported connection. {external(STEAM, "Steam product features")}</p><p>For demo carry-over and player count, see the <a href="/warhammer-survivors/co-op/#save">save and multiplayer explanation</a>. For mobile storefront details, see <a href="/warhammer-survivors/#ios">iPhone and iPad purchase checks</a>.</p>'),
         ], 'combat'),
        ('followers', 'Warhammer Survivors: Get 2 Followers and Unlock Items', 'Follow a reported 40K route to two followers and Bugman’s Tankard, then extend the squad toward five followers and the Figure Case objective.', 'How to get two followers in Warhammer Survivors',
         '<p><strong>On the 40K side, try Malum Caedo with the unlocked Lasgun and Shield of Faith.</strong> These weapons bring their users into your squad. The launch item guide reports that having two followers unlocks Bugman’s Tankard. Keep the two-follower objective separate from the later five-follower target.</p>', [
            ('prepare', 'Prepare the two weapon choices', f'<ol><li>Rescue Trooper Bartosz Kozlowski on Imperial Bastion and unlock his Lasgun for future runs.</li><li>Unlock Sister Superior Amalia Novena. The character guide lists a 400-coin purchase.</li><li>The item guide reports unlocking Shield of Faith by surviving five minutes with Amalia. Check the associated Objective after that run.</li><li>Start a new 40K run as Malum Caedo. Take Lasgun and Shield of Faith when they are offered.</li></ol><p>Those prerequisites combine the launch character, item and follower guides. Each requirement applies to its named task. {external(CHARACTERS, "Character unlock report")} · {external(ITEMS, "Item unlock report")}</p>'),
            ('two', 'Check the two-follower objective', f'<p>The reported route recruits Kozlowski through Lasgun and Amalia through Shield of Faith. Check your follower count after taking both. If one weapon has not appeared, check its unlock Objective first. A completed unlock makes the item eligible for future choices rather than guaranteeing the next offered selection.</p><p>Bugman’s Tankard is listed against the requirement to have two followers. Check that objective in your selected universe after reaching the count. The reports do not establish that this 40K route completes the other universe’s objective. {external(ITEMS, "Bugman’s Tankard unlock report")}</p>'+visual),
            ('five', 'Extend the route toward five followers', f'<p>Destructoid’s follower guide describes the same Malum Caedo loadout and upgrading Lasgun to level 6. It reports that Kozlowski’s additional soldiers, together with Amalia, complete the five-follower target and unlock Figure Case. Use the displayed objective count to distinguish the initial two recruits from the later expanded squad. {external(FOLLOWERS, "Reported five-follower route, 10 November")}</p><p>This is a published route, with no full-run test by this site. If the displayed counter differs, record your build, universe, weapon ranks and unlocked objectives before comparing advice for another version.</p>'),
            ('next', 'Use the unlocked companion in a recipe', '<p>Bugman’s Tankard is reported beside Shield of Faith in 40K and Nebulous Sea Fog in Age of Sigmar. Use the <a href="/warhammer-survivors/evolutions/">evolution table</a> for your selected universe.</p><p>For human player count, open the <a href="/warhammer-survivors/co-op/">co-op guide</a>. For missing Dice Cube, use the <a href="/warhammer-survivors/dice-cube/">universe-specific unlock checks</a>.</p>'),
         ], 'squad'),
        ('dice-cube', 'Warhammer Survivors Dice Cube Unlock: 40K and AoS', 'Unlock Dice Cube with the correct universe objective, distinguish it from D6 Dice, and find the Boltgun or Boltstorm Pistol evolution pairing.', 'How to unlock Dice Cube in Warhammer Survivors',
         '<p><strong>In 40K, get D6 Dice to level 6. In Age of Sigmar, hold four weapons at once.</strong> The launch item guide reports different Dice Cube unlock conditions for the two universes. Check the Objective in the universe you are currently playing.</p>', [
            ('unlock', 'Follow the condition for your universe', f'<div class="table-wrap" tabindex="0" role="region" aria-label="Dice Cube unlock conditions"><table><thead><tr><th>Universe</th><th>Reported objective</th><th>Action</th></tr></thead><tbody><tr><td>Warhammer 40,000</td><td>D6 Dice reaches level 6</td><td>Take the D6 Dice weapon and invest upgrades into it. Check the unlock after completing the condition.</td></tr><tr><td>Age of Sigmar</td><td>Hold four weapons at once</td><td>Take four weapon slots in one run. Check the Dice Cube objective afterward.</td></tr></tbody></table></div><p>The launch item report gives both conditions and says universe objectives must be completed separately. {external(ITEMS, "Destructoid launch item unlocks")}</p>'),
            ('pairing', 'Choose the weapon that uses Dice Cube', '<p>Dice Cube is the passive companion for <strong>Boltgun → Heavy Bolter</strong> in 40K and <strong>Boltstorm Pistol → Typhoon Crossbow</strong> in Age of Sigmar. D6 Dice is the weapon used in the 40K unlock condition. After unlocking the passive, you still need to choose Dice Cube in the run where you want the evolution.</p><p>Use the <a href="/warhammer-survivors/evolutions/">recipe finder</a> and search Dice Cube to compare the two reported pairings. For an evolution attempt, assemble the weapon/passive combination and check the weapon upgrade and chest conditions on that page.</p>'+combat),
            ('missing', 'If the passive still does not appear', '<ol><li>Check which universe is selected.</li><li>Check the exact Dice Cube Objective and its completion state.</li><li>Distinguish the D6 Dice weapon from the Dice Cube passive in your loadout.</li><li>Check later level-up choices after the unlock. The requirement does not establish a guaranteed drop time.</li></ol><p>If the current Objective differs from the report, keep its displayed wording and game version when asking support. Exact selection odds and a guaranteed appearance time have not been established.</p><p>For a different unlock, continue to <a href="/warhammer-survivors/followers/">two followers and Bugman’s Tankard</a>.</p>'),
         ], 'combat'),
    ]
    for slug, title, description, heading, answer, sections, stem in pages:
        file = ROOT/'warhammer-survivors'/slug/'index.html'
        file.parent.mkdir(parents=True, exist_ok=True)
        text = render(template, BASE+slug+'/', title, description, heading, answer, sections, stem)
        if slug == 'dice-cube':
            text = text.replace(combat, objectives)
        if slug in ['dice-cube', 'followers']:
            text = text.replace('https://megabonk.org/assets/warhammer-survivors/'+stem+'-1280.webp', 'https://megabonk.org/assets/warhammer-survivors/objectives.webp')
        text = text.replace('WARHAMMER SURVIVORS · OCTOBER DEMO / PRE-RELEASE', 'WARHAMMER SURVIVORS · PLAYER GUIDE')
        text = text.replace('Checked 8 November 2026 · Full game planned for 10 November', 'Checked 11 November 2026 · Launch-version reports')
        write_html(file, text, encoding='utf8')

def connect(route, text):
    if route == BASE:
        links = '<section id="progression-guides"><h2>Saves and unlocks</h2><p><a href="/warhammer-survivors/cross-save/">Check progress transfer between your copies →</a></p><p><a href="/warhammer-survivors/followers/">Get two followers and unlock Bugman’s Tankard →</a></p><p><a href="/warhammer-survivors/dice-cube/">Unlock Dice Cube in your selected universe →</a></p></section>'
        text = text.replace('<p><a href="#guide">Back to top', links+'<p><a href="#guide">Back to top')
    elif route.endswith('/co-op/'):
        text = text.replace('<section id="save">', '<section id="save"><p><a href="/warhammer-survivors/cross-save/">Check Xbox Play Anywhere, Steam Cloud and cross-store save boundaries →</a></p>')
        text = text.replace('<section id="squad">', '<section id="squad"><p><a href="/warhammer-survivors/followers/">Follow the two-follower and five-follower unlock route →</a></p>')
    elif route.endswith('/evolutions/'):
        details = '<section id="weapon-checks"><h2>Start with your weapon’s unlock and companion</h2><ul><li><strong>Chainsword → Eviscerator Chainsword</strong> uses Tape Measure. The launch item guide reports surviving one minute in a 40K run as the Tape Measure unlock.</li><li><strong>Lasgun → Meltagun</strong> uses Gauntlet. Unlock Kozlowski and Lasgun before planning that weapon’s run.</li><li><strong>Boltgun → Heavy Bolter</strong> uses Dice Cube. <a href="/warhammer-survivors/dice-cube/">Check the Dice Cube objective</a>.</li><li><strong>Whirlwind Battery → Orbital Bombardment</strong> uses Liquid Green Stuff.</li><li><strong>Frag Grenade → Ripper Pistol</strong> uses Bandolier. The launch item report gives Boltgun level 4 as Bandolier’s unlock condition. This is separate from upgrading Bandolier during the evolution attempt.</li></ul><p>Unlock conditions are from <a href="'+ITEMS+'" target="_blank" rel="noopener noreferrer">Destructoid’s launch item report ↗<span class="sr-only"> (opens in a new tab)</span></a>. The table above supplies recipe names. Complete the selected weapon’s upgrade sequence before trying the reported chest trigger.</p></section>'
        text = text.replace('<section id="missing">', details+'<section id="missing">')
    return text
